 @Test @Order(9) void approvalTimeEffectiveRuleSnapshotAndCompletionIntervalUseRoundStart()throws Exception{
  String t=closed(false);var original=f.detail(h.a,t);var q=apply(t);String rule=h.json.writeValueAsString(Map.of("version","SLA_B11_TEST_V2","responseMinutes",Map.of("P1",1,"P2",2,"P3",3),"resolutionHours",Map.of("P1",1,"P2",2,"P3",3)));restart(Map.of("IAS_TICKET_SLA_RULE",rule));try{var approved=decide(t,q,true,true);String round=approved.get("newRoundId").toString();var d=f.detail(h.a,t);Instant start=Instant.parse(d.get("roundStartedAt").toString());assertEquals("SLA_B11_TEST_V2",d.get("ruleVersion"));assertEquals(start.plusSeconds(120).toString(),((Map<?,?>)d.get("sla")).get("responseDueAt"));assertEquals(start.plusSeconds(7200).toString(),((Map<?,?>)d.get("sla")).get("resolutionDueAt"));assertEquals(original.get("submittedAt"),d.get("submittedAt"));assertNull(d.get("firstResponseAt"));acceptTarget(t,approved);assertNull(f.detail(h.a,t).get("firstResponseAt"));var invalid=solveFor(f.other,t);invalid.put("completedAt",original.get("submittedAt"));h.status(400,f.action(f.other,t,"solutions",invalid,UUID.randomUUID().toString()));recordFor(f.other,t,"CUSTOMER_VISIBLE","0.25");finish(f.other,t);var frozen=f.detail(h.a,t);var request3=apply(t);restart(Map.of());var approved3=decide(t,request3,true,false);var current=f.detail(h.a,t);assertEquals("SLA_V1",current.get("ruleVersion"));assertNull(current.get("firstResponseAt"));assertEquals("0.00",current.get("recordedWorkHours"));assertEquals(frozen.get("timing"),get(h.a,"/api/ticket/tickets/"+t+"/rounds/"+round).get("timing"));assertEquals(original.get("sla"),get(h.a,"/api/ticket/tickets/"+t+"/rounds/"+original.get("roundId")).get("sla"));note("controlled effective SLA V2 frozen only at approval, next V1 independent; original submission immutable; pre-round completedAt denied and prior frozen timing unchanged",t);}finally{if(h.roleEnvironment.containsKey("ticket"))restart(Map.of());}
 }
 @Test @Order(10) void candidateScannerAuditRollbackStableRetryAndDefaultStartupSweep()throws Exception{
  restart(Map.of("IAS_TICKET_REOPEN_SCAN_ENABLED","false","IAS_TICKET_TRANSFER_SCAN_ENABLED","false"));
  try{for(String fault:List.of("TRANSFER_NO_LONGER_APPLICABLE","WORKFLOW_REOPEN_RELEASE_INVALID")){
   String t=closed(false);var approved=decide(t,apply(t),true,true);String assignment=approved.get("assignmentId").toString();var transfer=x.input(t);transfer.putAll(Map.of("targetDepartmentId",Long.toString(f.dept1),"targetEngineerUserId",Long.toString(f.engineerId),"reason","本轮安排其他合格工程师协调后续处理。"));var pending=f.action(h.a,t,"transfer-requests",transfer,UUID.randomUUID().toString());h.status(200,pending);String q=h.body(pending).get("transferRequestId").toString(),op=UUID.nameUUIDFromBytes(("reopen-invalid-assignment:"+assignment).getBytes(java.nio.charset.StandardCharsets.UTF_8)).toString(),constraint="it_b11scan_"+op.substring(0,8);targetFacts(TransferFlowTest.ENG.stream().filter(p->!p.equals("ticket.record")).toList(),false);
   try{var before=f.detail(h.a,t);try(var db=f.files.ticketDb(false)){h.update(db,"ALTER TABLE ticket_audit ADD CONSTRAINT "+constraint+" CHECK(NOT(operation_id='"+op+"' AND action='"+fault+"'))");}
    try{assertThrows(Exception.class,()->scanCandidate(t));var after=f.detail(h.a,t);for(String field:List.of("roundId","status","rowVersion","assignment","firstResponseAt","currentTransfer","sla"))assertEquals(before.get(field),after.get(field));try(var db=f.files.ticketDb(false)){assertEquals(0,h.scalar(db,"SELECT COUNT(*) FROM ticket_transfer_end WHERE request_id=?",q));assertEquals(0,h.scalar(db,"SELECT COUNT(*) FROM ticket_action_operation WHERE operation_id=?",op));assertEquals(0,h.scalar(db,"SELECT COUNT(*) FROM ticket_coordination_event WHERE ticket_id=?",t));assertEquals(0,h.scalar(db,"SELECT COUNT(*) FROM ticket_audit WHERE operation_id=?",op));}}
    finally{try(var db=f.files.ticketDb(false)){h.update(db,"ALTER TABLE ticket_audit DROP CHECK "+constraint);}}
    if(fault.equals("TRANSFER_NO_LONGER_APPLICABLE")){assertTrue(scanCandidate(t));assertFalse(scanCandidate(t));}else{restart(Map.of());long until=System.nanoTime()+java.util.concurrent.TimeUnit.SECONDS.toNanos(70);while(System.nanoTime()<until&&!f.detail(h.a,t).get("status").equals("WAITING_ASSIGNMENT"))Thread.sleep(200);}
    var released=f.detail(h.a,t);assertEquals("WAITING_ASSIGNMENT",released.get("status"));assertNull(released.get("currentTransfer"));assertNull(released.get("firstResponseAt"));assertEquals(before.get("sla"),released.get("sla"));assertEquals(before.get("roundId"),released.get("roundId"));try(var db=f.files.ticketDb(false)){assertEquals(1,h.scalar(db,"SELECT COUNT(*) FROM ticket_transfer_end WHERE request_id=? AND reason='SOURCE_ASSIGNMENT_RELEASED'",q));assertEquals(1,h.scalar(db,"SELECT COUNT(*) FROM ticket_action_operation WHERE operation_id=? AND actor_user_id=0",op));assertEquals(1,h.scalar(db,"SELECT COUNT(*) FROM ticket_audit WHERE operation_id=? AND action='WORKFLOW_REOPEN_RELEASE_INVALID'",op));}note("SYSTEM candidate release actual "+fault+" CHECK rollback then "+(fault.startsWith("WORKFLOW")?"default JAR startup sweep":"stable original system UUID retry")+", unique NLA/operation and no SLA/first-response reset",t);
   }finally{targetFacts(TransferFlowTest.ENG,true);}
  }}finally{if(h.roleEnvironment.containsKey("ticket"))restart(Map.of());}
 }
